def render(asset):
    asset_id, title, description, default_color, parts = asset
    lines = [
        "// SPDX-License-Identifier: CC0-1.0",
        "// Original low-poly theatre-production scene prop, millimetres, Z up, base at z = 0.",
        "",
        "meta({",
        f"  name: {json.dumps(asset_id)},",
        "  license: 'CC0-1.0',",
        f"  title: {json.dumps(title)},",
        f"  description: {json.dumps(description + ' Stylized scene geometry. Knobs: overall scale and asset color.')},",
        "  tags: ['theatre production', 'stagecraft', 'performing arts', 'low poly', 'scene prop'],",
        "  kit: 'theatre-production',",
        "  category: 'prop',",
        "  origin: 'base',",
        "  compat: ['theatre', 'theater', 'stagecraft', 'performing-arts', 'scene'],",
        "  triangleBudget: 1800,",
        "});",
        "",
        "const scale = param('scale', 1, { min: 0.7, max: 1.3, step: 0.05, label: 'Overall scale' });",
        f"const color = param('color', {json.dumps(default_color)}, {{ label: 'Asset color' }});",
        "const b = (x:number,y:number,z:number,w:number,d:number,h:number) => box(w,d,h,true).translate(x,y,z+h/2).scale(scale);",
        "const c = (x:number,y:number,z:number,h:number,r:number,s:number) => cylinder(h,r,s).translate(x,y,z).scale(scale);",
    ]
    if any(part[0] == "cylinder-y" for part in parts):
        lines.append("const cy = (x:number,y:number,z:number,h:number,r:number,s:number) => cylinder(h,r,s).rotateX(90).translate(x,y,z).scale(scale);")
    lines.extend(["", f"const p = assembly({json.dumps(asset_id)});"])
    for part in parts:
        if part[0] == "box":
            _, name, x, y, z, w, d, h = part
            shape = f"b({x},{y},{z},{w},{d},{h})"
        elif part[0] == "cylinder-y":
            _, name, x, y, z, h, r, segments = part
            shape = f"cy({x},{y},{z},{h},{r},{segments})"
        else:
            _, name, x, y, z, h, r, segments = part
            shape = f"c({x},{y},{z},{h},{r},{segments})"
        lines.append(f"p.part({json.dumps(name)}, {shape}.color(color));")
    lines.extend(["", "return p.model();", ""])
    return "\n".join(lines)


ids = [asset[0] for asset in ASSETS]
if len(ASSETS) != 52 or len(ids) != len(set(ids)):
    raise SystemExit("theatre-production wave must contain 52 uniquely named assets")
if any(part[4] < 0 for asset in ASSETS for part in asset[4]):
    raise SystemExit("all theatre-production components must be on or above z=0")

for asset in ASSETS:
    (KIT / f"{asset[0]}.kcad.ts").write_text(render(asset))

(KIT / "kit.json").write_text(
    json.dumps(
        {
            "title": "Theatre production",
            "description": "Original low-poly staging, scenery, rigging, lighting, backstage, and touring props with editable scale and color controls.",
        },
        indent=2,
    )
    + "\n"
)
print(f"generated {len(ASSETS)} theatre-production assets")
